const field=(key,label,options={})=>({key,label,...options});
const providerFields=[field('BASE_URL','API 基础地址',{placeholder:'https://供应商地址/v1',required:true}),field('API_KEY','API Key',{secret:true,required:true}),field('MODEL','主模型 ID / 接入点 ID',{required:true}),field('INPUT_CNY_PER_M','输入单价（元 / 百万 Token）',{number:true,required:true}),field('OUTPUT_CNY_PER_M','输出单价（元 / 百万 Token）',{number:true,required:true}),field('CACHE_INPUT_CNY_PER_M','缓存读取单价',{number:true}),field('FALLBACK_MODEL','备用模型 ID'),field('FALLBACK_INPUT_CNY_PER_M','备用输入单价',{number:true}),field('FALLBACK_OUTPUT_CNY_PER_M','备用输出单价',{number:true}),field('FALLBACK_CACHE_INPUT_CNY_PER_M','备用缓存读取单价',{number:true})];
export const integrations=[...['DEEPSEEK','QWEN','KIMI','DOUBAO','MINIMAX'].map((id,i)=>({id,name:['DeepSeek','通义千问','Kimi','豆包','MiniMax'][i],type:'provider',fields:providerFields})),{id:'FEISHU',name:'飞书',type:'notification',fields:[field('WEBHOOK','机器人 Webhook 地址',{secret:true,required:true}),field('SECRET','签名密钥（可选）',{secret:true})]},{id:'WECOM',name:'企业微信',type:'notification',fields:[field('WEBHOOK','机器人 Webhook 地址',{secret:true,required:true})]}];
export const definition=id=>integrations.find(x=>x.id===id);
export function validateConfig(id,values,{complete=false,hasSecret={}}={}){const def=definition(id);if(!def)throw Error('未知集成');const result={};for(const f of def.fields){const raw=values[f.key]??'';if(typeof raw!=='string'&&typeof raw!=='number')throw Error(f.label+'格式无效');const value=String(raw).trim();if(value.length>4096||/[\x00-\x1f\x7f]/.test(value))throw Error(f.label+'不能包含换行或控制字符');if(f.number&&value!==''&&(!Number.isFinite(Number(value))||Number(value)<0))throw Error(f.label+'需为非负数字');if(complete&&f.required&&!value&&!hasSecret[f.key])throw Error('请填写'+f.label);result[f.key]=value;}
 if(result.BASE_URL){let u;try{u=new URL(result.BASE_URL)}catch{throw Error('API 基础地址无效')}if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error('地址只能使用 HTTP(S)，不能包含账号、查询参数或片段');if(u.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw Error('远程 API 地址必须使用 HTTPS');if(/\/(chat\/completions|models)\/?$/.test(u.pathname))throw Error('请填写基础地址，不要包含 /chat/completions 或 /models');result.BASE_URL=result.BASE_URL.replace(/\/$/,'');}
 if(result.WEBHOOK){let u;try{u=new URL(result.WEBHOOK)}catch{throw Error('Webhook 地址无效')}if(u.protocol!=='https:'||u.username||u.password||u.hash)throw Error('Webhook 必须为不含账号的 HTTPS 地址');}
 if(complete&&result.FALLBACK_MODEL&&(!result.FALLBACK_INPUT_CNY_PER_M||!result.FALLBACK_OUTPUT_CNY_PER_M))throw Error('设置备用模型时需填写备用输入和输出单价');
 return result;
}
export function envFile(id,values,format='dotenv'){if(!['dotenv','docker'].includes(format))throw Error('未知环境文件格式');const validated=validateConfig(id,values);if(format==='docker')return '# AgentGuard Docker --env-file format (not Node dotenv)\n# Values are literal; do not add surrounding quotes. Keep this file private.\n'+Object.entries(validated).map(([key,value])=>id+'_'+key+'='+value).join('\n')+'\n';return '# AgentGuard '+definition(id).name+' configuration\n# Merge into your private .env; do not commit credentials.\n'+Object.entries(validated).map(([key,value])=>{const quote=!value.includes("'")?"'":!value.includes("`")?"`":!value.includes('"')&&!/\\[nr]/.test(value)?'"':null;if(!quote)throw Error('此值不能无损写入 Node 环境文件，请使用 Docker 格式或服务端加密配置');return id+'_'+key+'='+quote+value+quote}).join('\n')+'\n'}
export function workflowTemplate(platform,values){if(!['Dify','Coze','n8n'].includes(platform))throw Error('未知工作流平台');const url=new URL(values.url);if(!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw Error('服务地址无效');if(!/^[a-zA-Z0-9_-]{1,80}$/.test(values.task))throw Error('任务 ID 只能包含字母、数字、下划线和短横线');if(!['research','support','content'].includes(values.policy))throw Error('费用策略无效');const base=url.href.replace(/\/$/,'');return {platform,description:'HTTP 节点配置模板；需在平台创建节点和停止条件，不是原生插件。',steps:[{name:'创建任务',method:'POST',url:base+'/api/tasks',headers:{Authorization:'Bearer <平台密钥变量 INGEST_KEY>','Content-Type':'application/json'},body:{id:values.task,policy:values.policy,customer:values.customer,feature:values.feature}},{name:'每次操作前检查',method:'GET',url:base+'/api/tasks/'+values.task+'/decision',headers:{Authorization:'Bearer <平台密钥变量 INGEST_KEY>'},condition:'allow 时继续；degrade 切换备用模型；stop 或 approval 时终止分支'},{name:'上报操作结果',method:'POST',url:base+'/api/tasks/'+values.task+'/events',headers:{Authorization:'Bearer <平台密钥变量 INGEST_KEY>','Content-Type':'application/json'},body:{id:'<每次操作的唯一ID>',tool:'<工具名称>',input:{},cost:0,error:false},note:'cost 必须替换为实际费用；经过模型代理的调用不重复上报费用。'}]}}
